import{_ as n,r as s,o as t,c as o,b as e,d as r,a as l,e as i}from"./app.cc98d4e4.js";var h="/TIL/assets/image.50cc423f.png",d="/TIL/assets/image1.d8c4e3a8.png",c="/TIL/assets/image2.261287ec.png",p="/TIL/assets/image3.f7879ff3.png",g="/TIL/assets/image4.22df51a1.png",_="/TIL/assets/image5.5607ced3.png",m="/TIL/assets/image6.aade1339.png",u="/TIL/assets/image7.9f7fa50e.png",f="/TIL/assets/image8.ef03ffb6.png";const b={},v=l('<h1 id="\u110B\u1175\u1105\u1167\u11A8\u1109\u1165-\u110B\u1165\u1104\u1165\u11C2\u1100\u1166-\u110C\u1161\u11A8\u1109\u1165\u11BC\u1112\u1162\u110B\u1163-\u110C\u1169\u11C2\u110B\u1173\u11AF\u1101\u1161" tabindex="-1"><a class="header-anchor" href="#\u110B\u1175\u1105\u1167\u11A8\u1109\u1165-\u110B\u1165\u1104\u1165\u11C2\u1100\u1166-\u110C\u1161\u11A8\u1109\u1165\u11BC\u1112\u1162\u110B\u1163-\u110C\u1169\u11C2\u110B\u1173\u11AF\u1101\u1161" aria-hidden="true">#</a> \uC774\uB825\uC11C, \uC5B4\uB5BB\uAC8C \uC791\uC131\uD574\uC57C \uC88B\uC744\uAE4C?</h1><h2 id="\u1107\u1162\u1100\u1167\u11BC" tabindex="-1"><a class="header-anchor" href="#\u1107\u1162\u1100\u1167\u11BC" aria-hidden="true">#</a> \uBC30\uACBD</h2><p>\uC694\uC998 \uC0AC\uB0B4\uCD94\uCC9C \uB355\uBD84\uC5D0 \uB9CE\uC740 \uBD84\uB4E4\uC758 \uC774\uB825\uC11C\uB97C \uC811\uD588\uACE0, \uC774 \uACFC\uC815\uC5D0\uC11C \uAF64 \uB9CE\uC740 \uC778\uC0AC\uC774\uD2B8\uB97C \uC5BB\uC744 \uC218 \uC788\uC5C8\uB2E4. \uC0AC\uC2E4 \uC791\uB144\uAE4C\uC9C0 \uBA58\uD1A0\uB9C1\uC744 \uD1B5\uD574 \uC774\uB825\uC11C \uC791\uC131 \uBC29\uBC95\uC5D0 \uB300\uD574 \uAF64 \uB9CE\uC740 \uC774\uC57C\uAE30\uB97C \uD588\uB294\uB370 \uC774\uC5D0 \uB300\uD574 \uC815\uB9AC\uD55C\uC801\uC774 \uC5C6\uC5B4\uC11C \uD55C \uBC88 \uC815\uB9AC\uD574\uBCF4\uB824\uACE0 \uD55C\uB2E4.</p><h2 id="\u1102\u1161\u1105\u1173\u11AF-\u1109\u1165\u11AF\u1106\u1167\u11BC\u1112\u1161\u1102\u1173\u11AB-\u1106\u116E\u11AB\u1109\u1165" tabindex="-1"><a class="header-anchor" href="#\u1102\u1161\u1105\u1173\u11AF-\u1109\u1165\u11AF\u1106\u1167\u11BC\u1112\u1161\u1102\u1173\u11AB-\u1106\u116E\u11AB\u1109\u1165" aria-hidden="true">#</a> \uB098\uB97C \uC124\uBA85\uD558\uB294 \uBB38\uC11C</h2><p>\uC774\uB825\uC11C\uB294 \uC5D4\uC9C0\uB2C8\uC5B4\uB9C1 \uAD00\uC810\uC5D0\uC11C \uC0DD\uAC01\uD558\uBA74 \uC77C\uC885\uC758 \uB098\uC5D0 \uB300\uD55C \uACF5\uC2DD\uBB38\uC11C\uC774\uC9C0 \uC54A\uC744\uAE4C?</p><p>\uAE30\uC220\uBB38\uC11C\uB294 \uBCF4\uD1B5 \uC774 \uAE30\uC220\uC5D0 \uB300\uD55C \uC18C\uAC1C, \uBAA9\uC801, \uB2E4\uB978 \uAE30\uC220\uACFC \uBE44\uAD50\uD588\uC744 \uB54C\uC758 \uC7A5\uB2E8\uC810, \uAC15\uC810, \uC0AC\uC6A9\uBC29\uBC95, \uAE30\uC5EC\uBC29\uBC95 \uB4F1\uC744 \uC81C\uACF5\uD55C\uB2E4. \u201C\uAE30\uC220\u201D\uC744 \u201C\uC0AC\uB78C\u201D\uC73C\uB85C \uBC14\uAFB8\uBA74 \uC774\uB825\uC11C\uC640 \uBE44\uC2B7\uD558\uB2E4\uACE0 \uC0DD\uAC01\uD55C\uB2E4.</p><p>\uB098\uC5D0 \uB300\uD55C \uC18C\uAC1C, \uB098\uC758 \uBAA9\uC801/\uBAA9\uD45C, \uC7A5\uB2E8\uC810\uACFC \uAC15\uC810, \uC0AC\uC6A9\uBC29\uBC95(\uC5B4\uB5A4 \uC5ED\uB7C9\uC774 \uC788\uACE0, \uB098\uB97C \uC5B4\uB5A4\uC2DD\uC73C\uB85C \uD65C\uC6A9\uD558\uBA74 \uB420\uC9C0 \uB4F1), \uD6A8\uACFC \uB4F1 \uB098\uC5D0 \uB300\uD55C \uC124\uBA85\uC11C\uB97C \uC791\uC131\uD558\uB294 \uAC83\uC5D0 \uAC00\uAE5D\uACE0 \uC774\uB97C \uD1A0\uB300\uB85C \u201C\uC5B4\uB5A4 \uBB38\uC81C\uB97C \uC5BC\uB9C8\uB098 \uC798 \uD574\uACB0\uD560 \uC218 \uC788\uB294\uAC00\u201D\uB97C \uC870\uC9C1\uC5D0\uC11C \uD310\uB2E8\uD558\uB294\uAC8C \uC544\uB2D0\uAE4C?</p><p>\uC5B4\uCA0C\uB4E0 \uC911\uC694\uD55C\uAC74 \uACB0\uAD6D \uB2E4\uB978 \uC774\uB4E4\uC5D0\uAC8C \u201C\uB098\uB97C \uD6A8\uACFC\uC801\uC774\uACE0 \uC815\uD655\uD558\uAC8C \uC124\uBA85\uD558\uB294 \uAC83\u201D \uC774\uB2E4. \uB108\uBB34 \uACFC\uC7A5\uD558\uBA74 \uC548 \uB418\uACA0\uC9C0\uB9CC, \uB610 \uB108\uBB34 \uB098\uC5D0\uB300\uD574\uC11C \uBAA8\uB974\uBA74 \uB098\uC5D0 \uB300\uD574 \uC124\uBA85\uD558\uAE30\uAC00 \uC27D\uC9C0 \uC54A\uB2E4.</p><h2 id="\u110B\u1168\u110C\u1166\u1105\u1173\u11AF-\u1110\u1169\u11BC\u1112\u1162-\u1107\u1175\u1100\u116D\u1112\u1162\u1107\u1169\u1100\u1175" tabindex="-1"><a class="header-anchor" href="#\u110B\u1168\u110C\u1166\u1105\u1173\u11AF-\u1110\u1169\u11BC\u1112\u1162-\u1107\u1175\u1100\u116D\u1112\u1162\u1107\u1169\u1100\u1175" aria-hidden="true">#</a> \uC608\uC81C\uB97C \uD1B5\uD574 \uBE44\uAD50\uD574\uBCF4\uAE30</h2><p>\uC544\uBB34\uB798\uB3C4 \uC608\uC81C\uAC00 \uC788\uC5B4\uC57C \uC640\uB2FF\uC744 \uAC83 \uAC19\uC544\uC11C, \uD544\uC790\uAC00 2022\uB144\uB3C4\uC5D0 \uC791\uC131\uD55C \uC774\uB825\uC11C\uC640 2025\uB144\uB3C4\uC5D0 \uC791\uC131\uD55C \uC774\uB825\uC11C\uB97C \uD1B5\uD574 \uBE44\uAD50\uD574\uBCF4\uACE0\uC790 \uD55C\uB2E4.</p><h3 id="as-is-2022" tabindex="-1"><a class="header-anchor" href="#as-is-2022" aria-hidden="true">#</a> AS-IS(2022)</h3><p><span class="link-preview"><a href="https://junilhwang.notion.site/ver-2022-1a0514bc46548021880ac0ef588639a2?pvs=74" target="_blank" rel="noopener noreferrer"><span class="link-preview-image"><img src="https://app.notion.com/images/meta/default.png" alt="Notion | Where teams and agents work together"></span><span class="link-preview-content"><span class="link-preview-title">Notion | Where teams and agents work together</span><span class="link-preview-description">Made in Notion, the connected workspace where AI agents and teams organize docs, projects and knowledge together.</span><span class="link-preview-url">Notion</span></span></a></span></p><p>\uC90C\uC778\uD130\uB137 \uC7AC\uC9C1 \uC2DC\uC808 \uC791\uC131\uD55C \uC774\uB825\uC11C\uB97C \uBCF4\uBA74 <s>\uC9C4\uC9DC \uAC1C\uD310</s>\uC774\uB2E4.</p><div class="flow items-3"><img src="'+h+'" alt="1"><img src="'+d+'" alt="2"><img src="'+c+'" alt="3"></div><p>\uC774\uB825\uC11C\uB97C \uC791\uC131\uD560 \uB2F9\uC2DC\uC5D0, \uC774\uC9C1\uC744 \uD574\uBCF8\uC801\uC774 \uC5C6\uAE30 \uB54C\uBB38\uC5D0 \uC5B4\uB5A4\uC2DD\uC73C\uB85C \uC774\uB825\uC11C\uB97C \uC791\uC131\uD574\uC57C \uC88B\uC740\uC9C0\uC5D0 \uB300\uD55C \uC0DD\uAC01\uC744 \uC544\uC608 \uC548 \uD588\uC5C8\uB2E4. \uC774\uAC83\uC800\uAC83 \uD588\uB358 \uAC83\uB4E4\uC740 \uB9CE\uC740\uB370, \uC774\uAC78 \uD6A8\uACFC\uC801\uC73C\uB85C \uC5B4\uD544\uD558\uB294 \uAC8C \uBBF8\uC219\uD588\uB2E4. \uCF54\uB4DC\uB97C \uC791\uC131\uD558\uB294 \uAC83\uACFC \uBE44\uC2B7\uD558\uB2E4. \uC720\uC0AC\uD55C \uB0B4\uC6A9\uC774 \uB9CE\uACE0, \uC774\uB825\uC5D0 \uB300\uD55C \uC751\uC9D1\uC774 \uC548 \uB418\uC5B4\uC788\uACE0, \uC5B4\uB5A4 \uC758\uB3C4\uB85C \uBB34\uC5C7\uC744 \uC124\uBA85\uD558\uACE0\uC790 \uD588\uB294\uC9C0\uB97C \uC804\uD600 \uC0DD\uAC01\uD558\uC9C0 \uC54A\uC558\uB2E4. \uADF8\uB0E5 \uC77D\uB294 \uC0AC\uB78C\uC774 \uC54C\uC544\uC11C \uD574\uC11D\uD574\uC8FC\uACA0\uC9C0 \uD558\uB294 \uB9C8\uC74C\uC774\uC5C8\uB2EC\uAE4C. <s>\uC194\uC9C1\uD788 \uC774\uB825\uC11C \uC791\uC131\uD558\uAE30\uAC00 \uB108\uBB34 \uADC0\uCC2E\uC558\uB358 \uAC83 \uAC19\uB2E4.</s></p><p>\uADF8\uB798\uC11C \uC774 \uC774\uB825\uC11C\uC758 \uBB38\uC81C\uC810\uC774 \uBB58\uAE4C? \uD558\uB098\uC529 \uB72F\uC5B4\uBCF4\uC790.</p><h4 id="_1-\u110C\u116E\u11BC\u1107\u1169\u11A8-\u1111\u116D\u1112\u1167\u11AB" tabindex="-1"><a class="header-anchor" href="#_1-\u110C\u116E\u11BC\u1107\u1169\u11A8-\u1111\u116D\u1112\u1167\u11AB" aria-hidden="true">#</a> 1) \uC911\uBCF5 \uD45C\uD604</h4><ul><li>\u201C\uD504\uB860\uD2B8\uC5D4\uB4DC \uC11C\uBC84 \uAC1C\uBC1C \uBC0F \uC6B4\uC601\u201D \uD639\uC740 \u201C\uAC1C\uBC1C \uBC0F \uC6B4\uC601\u201D, \u201C\uAC1C\uBC1C/\uC6B4\uC601\u201D \uB4F1\uC758 \uD45C\uD604\uC774 \uBC18\uBCF5\uB418\uACE0 \uC788\uB2E4.</li><li>\uAE30\uC220\uC2A4\uD0DD\uB3C4 \uC911\uBCF5\uB41C\uB2E4. \uD2B9\uD788 \u201C\uC90C \uD3EC\uD138\uC11C\uBE44\uC2A4 \uD480\uC2A4\uD0DD \uAC1C\uBC1C \uBC0F \uC6B4\uC601\u201D \uCABD\uC740 \uBD88\uD544\uC694\uD558\uAC8C \uAE30\uC220\uC2A4\uD0DD\uC744 \uB9CE\uC774 \uB098\uC5F4\uD558\uACE0 \uC788\uB2E4.</li></ul><h4 id="_2-a\u1105\u1173\u11AF-\u1112\u1162\u11BB\u110B\u1173\u11B7-\u110B\u1171\u110C\u116E\u110B\u1174-\u1111\u116D\u1112\u1167\u11AB\u110B\u1175-\u1106\u1161\u11AD\u1100\u1169-\u1106\u1169\u11A8\u110C\u1165\u11A8-\u110B\u1175\u11B7\u1111\u1162\u11A8\u1110\u1173-\u1105\u1165\u1102\u1175\u11BC\u1111\u1169\u110B\u1175\u11AB\u1110\u1173-\u1103\u1173\u11BC\u110B\u1175-\u110B\u1165\u11B9\u1103\u1161" tabindex="-1"><a class="header-anchor" href="#_2-a\u1105\u1173\u11AF-\u1112\u1162\u11BB\u110B\u1173\u11B7-\u110B\u1171\u110C\u116E\u110B\u1174-\u1111\u116D\u1112\u1167\u11AB\u110B\u1175-\u1106\u1161\u11AD\u1100\u1169-\u1106\u1169\u11A8\u110C\u1165\u11A8-\u110B\u1175\u11B7\u1111\u1162\u11A8\u1110\u1173-\u1105\u1165\u1102\u1175\u11BC\u1111\u1169\u110B\u1175\u11AB\u1110\u1173-\u1103\u1173\u11BC\u110B\u1175-\u110B\u1165\u11B9\u1103\u1161" aria-hidden="true">#</a> 2) \u201CA\uB97C \uD588\uC74C\u201D \uC704\uC8FC\uC758 \uD45C\uD604\uC774 \uB9CE\uACE0 \uBAA9\uC801/\uC784\uD329\uD2B8/\uB7EC\uB2DD\uD3EC\uC778\uD2B8 \uB4F1\uC774 \uC5C6\uB2E4.</h4><p>\uAC00\uB839, \u201C\uD504\uB860\uD2B8\uC5D4\uB4DC \uD45C\uC900\uD654 \uD328\uD0A4\uC9C0 \uAD00\uB9AC\u201D \uC5D0 \uB300\uD55C \uBD80\uBD84\uC744 \uBCF4\uBA74 \uC774\uAC8C \uC65C \uD544\uC694\uD588\uB294\uC9C0, \uC5B4\uB5A4 \uC758\uC0AC \uACB0\uC815 \uACFC\uC815\uC774 \uC788\uC5C8\uB294\uC9C0, \uC5B4\uB5A4 \uD6A8\uACFC\uAC00 \uC788\uC5C8\uB294\uC9C0\uC5D0 \uB300\uD55C \uB0B4\uC6A9\uC774 \uC544\uC608 \uC5C6\uB2E4.</p><h4 id="_3-\u1103\u1161\u11BC\u110B\u1167\u11AB\u1112\u1161\u11AB-\u1102\u1162\u110B\u116D\u11BC\u110B\u1175-\u1103\u1161\u11B7\u1100\u1167\u110B\u1175\u11BB\u1103\u1161" tabindex="-1"><a class="header-anchor" href="#_3-\u1103\u1161\u11BC\u110B\u1167\u11AB\u1112\u1161\u11AB-\u1102\u1162\u110B\u116D\u11BC\u110B\u1175-\u1103\u1161\u11B7\u1100\u1167\u110B\u1175\u11BB\u1103\u1161" aria-hidden="true">#</a> 3) \u201C\uB2F9\uC5F0\uD55C\u201D \uB0B4\uC6A9\uC774 \uB2F4\uACA8\uC788\uB2E4.</h4><img src="'+p+'" alt="image3" width="500"><ul><li>\uCD5C\uC0C1\uB2E8\uC5D0 \uC788\uB294 \uC18C\uAC1C\uCABD\uC5D0 \uC791\uC131\uD55C \uB0B4\uC6A9\uC774 \uADF8\uB807\uB2E4. \uC5B4\uB5BB\uAC8C\uBCF4\uBA74 \uAC1C\uBC1C\uC790\uB85C\uC11C \uAC16\uCDB0\uC57C\uD560 \uAE30\uBCF8\uC801\uC778 \uC18C\uC591\uC774\uACE0, \uC774\uB7F0 \uB0B4\uC6A9\uC744 \uC791\uC131 \uD588\uC744 \uB54C \uC77D\uB294 \uC785\uC7A5\uC5D0\uC11C\uB294 \uD070 \uC784\uD329\uD2B8\uAC00 \uC5C6\uB2E4\uACE0 \uC0DD\uAC01\uD55C\uB2E4.</li><li><code>\uBD88\uD544\uC694\uD558\uAC8C \uBCF5\uC7A1\uD55C \uB85C\uC9C1 -&gt; \uCD5C\uC18C\uD55C\uC758 \uB85C\uC9C1</code> , <code>\uD504\uB85C\uC81D\uD2B8 \uC77C\uC815\uC815\uAD00\uB9AC</code> , <code>\uAE30\uD68D\uC790, \uB514\uC790\uC774\uB108, \uBC31\uC5D4\uB4DC \uAC1C\uBC1C\uC790 \uB4F1\uACFC \uD611\uC5C5</code> <code>\uBAA8\uB2C8\uD130\uB9C1</code> <code>\uC0AC\uC6A9\uC790\uAC00 \uBC1C\uC0DD\uC2DC\uD0A8 \uC774\uBCA4\uD2B8\uC5D0 \uB300\uD55C \uD1B5\uACC4 \uC804\uC1A1</code> \uB4F1\uC758 \uD45C\uD604\uB3C4 \uB2F9\uC5F0\uD55C \uB0B4\uC6A9\uC5D0 \uAC00\uAE5D\uB2E4.</li><li>\uC720\uC0AC\uD558\uAC8C \uB9CE\uC740 \uC0AC\uB78C\uB4E4\uC774 \uC774\uB825\uC11C\uC5D0 \uB2F4\uB294 \uB0B4\uC6A9\uC740 \u201CCRUD\u201D \uAC19\uC740 \uAC83\uB4E4\uC774\uB2E4. \uB2F9\uC5F0\uD788 \uD574\uC57C \uD558\uB294 \uAC83\uB4E4\uC5D0 \uB300\uD574\uC11C\uB294 \uC774\uB825\uC11C\uC5D0 \uAD73\uC774 \uB2F4\uC9C0 \uC54A\uC544\uB3C4 \uBB34\uBC29\uD558\uB2E4\uACE0 \uC0DD\uAC01\uD55C\uB2E4.</li></ul><h4 id="_4-\u1106\u116E\u110B\u1165\u11BA\u110B\u1173\u11AF-\u1103\u1165-\u110C\u1161\u11AF-\u1112\u1161\u1102\u1173\u11AB-\u1109\u1161\u1105\u1161\u11B7-\u110B\u1175\u11AB\u110C\u1175\u110B\u1166-\u1103\u1162\u1112\u1161\u11AB-\u1102\u1162\u110B\u116D\u11BC\u110B\u1175-\u110B\u1165\u11B9\u1103\u1161" tabindex="-1"><a class="header-anchor" href="#_4-\u1106\u116E\u110B\u1165\u11BA\u110B\u1173\u11AF-\u1103\u1165-\u110C\u1161\u11AF-\u1112\u1161\u1102\u1173\u11AB-\u1109\u1161\u1105\u1161\u11B7-\u110B\u1175\u11AB\u110C\u1175\u110B\u1166-\u1103\u1162\u1112\u1161\u11AB-\u1102\u1162\u110B\u116D\u11BC\u110B\u1175-\u110B\u1165\u11B9\u1103\u1161" aria-hidden="true">#</a> 4) \u201C\uBB34\uC5C7\uC744 \uB354 \uC798 \uD558\uB294 \uC0AC\uB78C\u201D\uC778\uC9C0\uC5D0 \uB300\uD55C \uB0B4\uC6A9\uC774 \uC5C6\uB2E4.</h4><ul><li>\uC774\uAC8C \uC81C\uC77C \uC911\uC694\uD55C \uBD80\uBD84\uC774\uB77C\uACE0 \uC0DD\uAC01\uD55C\uB2E4. \uC774\uB825\uC11C\uB9CC \uBD24\uC744 \uB550 \uBB34\uC5C7\uC5D0 \uAC15\uC810\uC744 \uAC00\uC9C0\uACE0 \uC788\uB294 \uC0AC\uB78C\uC778\uC9C0 \uC54C\uAE30\uAC00 \uAF64 \uC5B4\uB835\uB2E4. \uC5B4\uB5A4 \uBB38\uC81C\uB97C \uB354 \uC798 \uD574\uACB0\uD560 \uC218 \uC788\uB294\uC9C0, \uC5B4\uB5A4 \uBB38\uC81C\uC5D0 \uB354 \uAD00\uC2EC\uC744 \uAC00\uC9C0\uACE0 \uC0B4\uD3B4\uBCF4\uB294 \uD3B8\uC778\uC9C0 \uB4F1\uC774 \uC5C6\uB2E4. \uC989, \uC774\uB825\uC11C\uB97C \uBD24\uC744 \uB54C \u201C\uC774 \uC0AC\uB78C\uACFC \uC5B4\uB5A4 \uC77C\uC744 \uD568\uAED8\uD574\uC57C \uC6B0\uB9AC \uC870\uC9C1\uC758 \uBB38\uC81C\uB97C \uC798 \uD480\uC5B4\uAC08 \uC218 \uC788\uC744\uAE4C?\u201D \uC5D0 \uB300\uD55C \uC758\uBB38\uC774 \uC0DD\uAE34\uB2E4.</li><li>\uB098\uC758 \uC9C1\uAD70\uC5D0 \uB300\uD574\uC11C\uB3C4 \uB098\uB9CC\uC758 \uC804\uBB38\uC131 \uD639\uC740 \uAD00\uC2EC\uC0AC\uAC00 \uD544\uC694\uD558\uB2E4. \uAE30\uBCF8\uAE30 \uC678\uC5D0 \u201C\uB354 \uC798 \uD560 \uC218 \uC788\uB294 \uC77C\u201D\uC744 \uAD6C\uCCB4\uD654 \uD558\uC5EC \uBCF4\uC5EC\uC904 \uC218 \uC788\uC5B4\uC57C \uD55C\uB2E4.</li></ul><div class="custom-container tip"><p class="custom-container-title">\uB3CC\uC774\uCF1C \uC0DD\uAC01\uD574\uBCF4\uBA74</p><p>\uB098\uB294 \uC774 \uC774\uB825\uC11C\uB97C \uC791\uC131\uD560 \uB2F9\uC2DC\uC5D0 <strong>\uC774\uB825\uC11C\uBCF4\uB2E8 \uC544\uD2F0\uD074\uC744 \uB354 \uC911\uC694\uD558\uAC8C \uC0DD\uAC01\uD588\uB2E4.</strong> \uC5B4\uCC28\uD53C \uB098\uC5D0 \uB300\uD55C \uB0B4\uC6A9\uC740 \uC774\uB825\uC11C\uB97C \uD1B5\uD574 \uB2E4 \uD45C\uD604\uD560 \uC218 \uC5C6\uB2E4\uACE0 \uC0DD\uAC01\uD588\uACE0, \uB098\uC5D0 \uB300\uD574 \uAD81\uAE08\uD55C\uAC8C \uB9CE\uB2E4\uBA74 \uACB0\uAD6D \uBE14\uB85C\uADF8 \uC544\uD2F0\uD074\uC744 \uCC38\uACE0\uD558\uACA0\uAC70\uB2C8 \uC2F6\uC5C8\uB2E4. \uC2E4\uC81C\uB85C \uC774\uC9C1 \uC900\uBE44\uD560 \uB2F9\uC2DC\uC5D0 \uBE14\uB85C\uADF8 \uC544\uD2F0\uD074\uC744 \uBCF4\uACE0 \uC5F0\uB77D\uC744 \uC8FC\uC2E0 \uBD84\uB4E4\uB3C4 \uB9CE\uC558\uB2E4. \uADF8\uB7EC\uB2E4\uBCF4\uB2C8 \uC774\uB825\uC11C\uB97C \uC911\uC694\uD558\uAC8C \uC0DD\uAC01\uD558\uC9C0 \uC54A\uC558\uACE0, \uD615\uC2DD\uC801\uC73C\uB85C \uC791\uC131\uD558\uB294 \uAC83\uC774\uB77C\uACE0 \uC0DD\uAC01\uD588\uC5C8\uB2E4.</p></div><h3 id="to-be-2025" tabindex="-1"><a class="header-anchor" href="#to-be-2025" aria-hidden="true">#</a> TO-BE(2025)</h3><p><span class="link-preview"><a href="https://junilhwang.notion.site/20250916-270514bc46548012b28befac880862ad?pvs=74" target="_blank" rel="noopener noreferrer"><span class="link-preview-image"><img src="https://app.notion.com/images/meta/default.png" alt="Notion | Where teams and agents work together"></span><span class="link-preview-content"><span class="link-preview-title">Notion | Where teams and agents work together</span><span class="link-preview-description">Made in Notion, the connected workspace where AI agents and teams organize docs, projects and knowledge together.</span><span class="link-preview-url">Notion</span></span></a></span></p><p>\uB124\uC774\uBC84 \uC7AC\uC9C1\uC2DC\uC808 \uC791\uC131\uD55C \uC774\uB825\uC11C\uC774\uAE34 \uD558\uC9C0\uB9CC \uB124\uC774\uBC84\uC758 \uC774\uB825 \uB9D0\uACE0 \uC90C\uC778\uD130\uB137\uC758 \uC774\uB825\uC744 \uC5B4\uB5A4\uC2DD\uC73C\uB85C \uAC1C\uC120\uD588\uB294\uC9C0 \uC0B4\uD3B4\uBCF4\uC790.</p><h4 id="_1-\u1109\u1169\u1100\u1162\u1105\u1173\u11AF-\u1112\u1161\u11AF-\u1104\u1162\u110B\u1166\u1102\u1173\u11AB-\u1103\u1161\u11BC\u110B\u1167\u11AB\u1112\u1161\u11AB-\u1102\u1162\u110B\u116D\u11BC-\u1107\u1169\u1103\u1161-\u1102\u1161\u1106\u1161\u11AB\u110B\u1174-\u1104\u116E\u1105\u1167\u11BA\u1112\u1161\u11AB-\u1100\u1161\u110E\u1175\u1100\u116A\u11AB-\u110B\u1173\u11AF-\u1103\u1161\u11B7\u110B\u1161\u1107\u1169\u1100\u1175" tabindex="-1"><a class="header-anchor" href="#_1-\u1109\u1169\u1100\u1162\u1105\u1173\u11AF-\u1112\u1161\u11AF-\u1104\u1162\u110B\u1166\u1102\u1173\u11AB-\u1103\u1161\u11BC\u110B\u1167\u11AB\u1112\u1161\u11AB-\u1102\u1162\u110B\u116D\u11BC-\u1107\u1169\u1103\u1161-\u1102\u1161\u1106\u1161\u11AB\u110B\u1174-\u1104\u116E\u1105\u1167\u11BA\u1112\u1161\u11AB-\u1100\u1161\u110E\u1175\u1100\u116A\u11AB-\u110B\u1173\u11AF-\u1103\u1161\u11B7\u110B\u1161\u1107\u1169\u1100\u1175" aria-hidden="true">#</a> 1) \uC18C\uAC1C\uB97C \uD560 \uB54C\uC5D0\uB294 \u201C\uB2F9\uC5F0\uD55C \uB0B4\uC6A9\u201D \uBCF4\uB2E4 \u201C\uB098\uB9CC\uC758 \uB69C\uB837\uD55C \uAC00\uCE58\uAD00\u201D\uC744 \uB2F4\uC544\uBCF4\uAE30.</h4><img src="'+g+'" alt="image4" width="500"><ul><li>\uBB34\uC5C7\uC5D0 \uAD00\uC2EC\uC744 \uAC00\uC9C0\uACE0 \uC788\uB294\uC9C0, \uC5B4\uB5A4 \uAC00\uCE58\uAD00\uC744 \uAC00\uC9C0\uACE0 \uC788\uB294\uC9C0, \uC5B4\uB5A4 \uC804\uB7B5\uC744 \uAC00\uC9C0\uACE0 \uC788\uB294\uC9C0 \uB4F1 \u201C\uAC1C\uBC1C\uC790\u201D \uB85C\uC11C\uC758 \uBAA8\uC2B5\uB3C4 \uC911\uC694\uD558\uC9C0\uB9CC \uACB0\uAD6D \u201C\uD669\uC900\uC77C\u201D \uC774\uB77C\uB294 \uC0AC\uB78C\uC744 \uC5B4\uB5A4\uC2DD\uC73C\uB85C \uD45C\uD604\uD558\uB294\uC9C0\uAC00 \uC911\uC694\uD558\uB2E4.</li><li>\uB3CC\uC774\uCF1C \uC0DD\uAC01\uD574\uBCF4\uBA74 \u201C<u><strong>\uAC1C\uBC1C\uC790</strong></u> \uD669\uC900\uC77C\u201D \uC5D0\uC11C \u201C\uAC1C\uBC1C\uC790 <u><strong>\uD669\uC900\uC77C</strong></u>\u201D \uD45C\uD604\uC758 \uD3EC\uCEE4\uC2A4\uAC00 \uBC14\uB010 \uAC83 \uAC19\uB2E4. \uB098\uB294 \uAC1C\uBC1C\uC790\uC774\uC9C0\uB9CC, \uAC1C\uBC1C\uC774\uB77C\uB294 \uAC83\uB3C4 \uC870\uC9C1\uC774 \uAC00\uC9C0\uACE0 \uC788\uB294 \uBB38\uC81C\uB97C \uAE30\uC220\uC801\uC73C\uB85C \uD480\uC5B4\uB098\uAC00\uB294 \uAC83\uC774\uACE0 \uD575\uC2EC\uC740 \u201C\uBB38\uC81C \uD574\uACB0\u201D\uC774\uB77C\uB294 \uAC83.</li><li>\uBB38\uC81C \uD574\uACB0\uC740 \uAE30\uC220\uC801\uC778 \uBC29\uC2DD\uB3C4 \uC788\uC9C0\uB9CC \uBE44\uAE30\uC220\uC801\uC778 \uBC29\uC2DD\uB3C4 \uBB34\uCC99 \uB9CE\uC774 \uC788\uC73C\uBA70 \uC774 \uB610\uD55C \uAC15\uC870\uD560 \uC218 \uC788\uB294 \uB2A5\uB825\uC774\uACE0 \uC5ED\uB7C9\uC774\uB2E4.</li></ul><h4 id="_2-\u110B\u1175\u1105\u1167\u11A8\u1109\u1165\u1105\u1173\u11AF-\u110C\u1161\u11A8\u1109\u1165\u11BC\u1112\u1161\u11AF-\u1103\u1161\u11BC\u1109\u1175\u110B\u1166-\u1100\u1175\u11C1\u110B\u1175-\u110B\u1175\u11BB\u1100\u1166-\u1100\u1169\u1106\u1175\u11AB\u1112\u1161\u1103\u1165\u11AB-\u1106\u116E\u11AB\u110C\u1166\u110B\u1166-\u1103\u1162\u1112\u1162-\u1103\u1161\u1105\u116F\u1107\u1169\u1100\u1175" tabindex="-1"><a class="header-anchor" href="#_2-\u110B\u1175\u1105\u1167\u11A8\u1109\u1165\u1105\u1173\u11AF-\u110C\u1161\u11A8\u1109\u1165\u11BC\u1112\u1161\u11AF-\u1103\u1161\u11BC\u1109\u1175\u110B\u1166-\u1100\u1175\u11C1\u110B\u1175-\u110B\u1175\u11BB\u1100\u1166-\u1100\u1169\u1106\u1175\u11AB\u1112\u1161\u1103\u1165\u11AB-\u1106\u116E\u11AB\u110C\u1166\u110B\u1166-\u1103\u1162\u1112\u1162-\u1103\u1161\u1105\u116F\u1107\u1169\u1100\u1175" aria-hidden="true">#</a> 2) \uC774\uB825\uC11C\uB97C \uC791\uC131\uD560 \uB2F9\uC2DC\uC5D0 \uAE4A\uC774 \uC788\uAC8C \uACE0\uBBFC\uD558\uB358 \uBB38\uC81C\uC5D0 \uB300\uD574 \uB2E4\uB904\uBCF4\uAE30</h4><img src="'+_+'" alt="image5" width="500"><ul><li>\uAF2D \uAE30\uC220\uC801\uC778 \uB0B4\uC6A9\uC774 \uC544\uB2C8\uC5B4\uB3C4 \uC0C1\uAD00 \uC5C6\uB2E4. \uC911\uC694\uD55C\uAC74 \u201C\uACE0\uBBFC\uC758 \uAE4A\uC774\u201D\uB77C\uACE0 \uC0DD\uAC01\uD55C\uB2E4. \uAE4A\uC774 \uC788\uAC8C \uACE0\uBBFC\uC774 \uC788\uB2E4\uBA74 \uC5B4\uB5A4\uC2DD\uC73C\uB85C\uB4E0 \uC774\uB825\uC11C\uC5D0 \uC798 \uB2F4\uC544\uBCF4\uBA74 \uC88B\uB2E4.</li><li>\uC774\uB825\uC11C\uB97C \uC791\uC131\uD560 \uB2F9\uC2DC\uC5D0 \u201C\uBCC0\uD654\u201D \uB77C\uB294 \uD0A4\uC6CC\uB4DC\uC5D0 \uAF42\uD600\uC788\uC5C8\uB2E4. \uBCC0\uD654\uB294 \uC5B4\uB5BB\uAC8C \uC2DC\uC791\uB418\uB294\uC9C0, \uC5B4\uB5A4 \uC804\uB7B5\uC744 \uAC00\uC9C0\uACE0 \uD589\uB3D9\uD574\uC57C \uD558\uB294\uC9C0 \uB4F1. \uADF8\uB798\uC11C \uAE38\uC9C0\uB9CC \uCD5C\uB300\uD55C \uC194\uC9C1\uD558\uC9C0\uB9CC \uB0B4\uC6A9\uC744 \uC555\uCD95\uD574\uC11C \uB2E4\uB918\uB2E4. \uC774\uAC8C \uC0C1\uB300\uBC29\uC774 \uB098\uB97C \uAE4A\uC774\uC788\uAC8C \uC774\uD574\uD558\uB294 \uB370 \uB3C4\uC6C0\uC774 \uB41C\uB2E4\uACE0 \uC0DD\uAC01\uD588\uB2E4.</li></ul><h4 id="_3-\u110B\u1167\u11A8\u1105\u1163\u11BC\u1100\u116A-\u1106\u116E\u11AB\u110C\u1166\u1112\u1162\u1100\u1167\u11AF\u110B\u1174-\u110C\u1169\u11BC\u1105\u1172\u1105\u1173\u11AF-\u1110\u1169\u1103\u1162\u1105\u1169-\u110F\u1161\u1110\u1166\u1100\u1169\u1105\u1161\u110B\u1175\u110C\u1175\u11BC-\u110C\u116E\u11BC\u1107\u1169\u11A8\u110C\u1166\u1100\u1165" tabindex="-1"><a class="header-anchor" href="#_3-\u110B\u1167\u11A8\u1105\u1163\u11BC\u1100\u116A-\u1106\u116E\u11AB\u110C\u1166\u1112\u1162\u1100\u1167\u11AF\u110B\u1174-\u110C\u1169\u11BC\u1105\u1172\u1105\u1173\u11AF-\u1110\u1169\u1103\u1162\u1105\u1169-\u110F\u1161\u1110\u1166\u1100\u1169\u1105\u1161\u110B\u1175\u110C\u1175\u11BC-\u110C\u116E\u11BC\u1107\u1169\u11A8\u110C\u1166\u1100\u1165" aria-hidden="true">#</a> 3) \uC5ED\uB7C9\uACFC \uBB38\uC81C\uD574\uACB0\uC758 \uC885\uB958\uB97C \uD1A0\uB300\uB85C \uCE74\uD14C\uACE0\uB77C\uC774\uC9D5 (\uC911\uBCF5\uC81C\uAC70)</h4><img src="'+m+'" alt="image6" width="300"><ul><li>\uC774\uB825\uC11C\uB97C \uD1B5\uD574 \uBCF4\uC5EC\uC8FC\uC5B4\uC57C \uD558\uB294 \uAC83\uC740 <strong>\uB0B4\uAC00 \uC5B4\uB5A4 \uC885\uB958\uC758 \uBB38\uC81C\uB97C \uD480\uC774\uD588\uACE0, \uC798 \uD480\uC774\uD560 \uC218 \uC788\uB294 \uC9C0</strong> \uB77C\uACE0 \uC0DD\uAC01\uD55C\uB2E4. \uD504\uB85C\uC81D\uD2B8\uB294 \uC774\uB97C \uD45C\uD604\uD558\uAE30 \uC704\uD55C \uC218\uB2E8\uC774\uB2E4.</li><li>\uADF8\uB798\uC11C \uC544\uC608 \uD504\uB85C\uC81D\uD2B8 \uB2E8\uC704\uAC00 \uC544\uB2C8\uB77C <strong>\uBB38\uC81C\uD574\uACB0\uC758 \uC885\uB958</strong>\uB97C \uD1A0\uB300\uB85C \uCE74\uD14C\uACE0\uB77C\uC774\uC9D5 \uD558\uC5EC \uD480\uC5B4\uB098\uAC00\uB294 \uAC8C \uB354 \uD6A8\uACFC\uC801\uC774\uB77C\uACE0 \uC0DD\uAC01\uD55C\uB2E4.</li></ul><h4 id="_4-\u110B\u116B-\u1111\u1175\u11AF\u110B\u116D\u1112\u1162\u11BB\u1102\u1173\u11AB\u110C\u1175-\u1105\u1173\u11AF-\u1106\u1167\u11BC\u1109\u1175\u1112\u1161\u1100\u1175" tabindex="-1"><a class="header-anchor" href="#_4-\u110B\u116B-\u1111\u1175\u11AF\u110B\u116D\u1112\u1162\u11BB\u1102\u1173\u11AB\u110C\u1175-\u1105\u1173\u11AF-\u1106\u1167\u11BC\u1109\u1175\u1112\u1161\u1100\u1175" aria-hidden="true">#</a> 4) \u201C\uC65C \uD544\uC694\uD588\uB294\uC9C0\u201D\uB97C \uBA85\uC2DC\uD558\uAE30</h4><p><img src="'+u+'" alt="image.png"></p><ul><li>\uB2E8\uC21C\uD558\uAC8C \u201C\uBB34\uC5C7\uC744 \uD588\uC74C\u201D \uC744 \uC5B8\uAE09\uD558\uB294 \uAC83 \uBCF4\uB2E4, \u201CA\uB77C\uB294 \uC774\uC720\uAC00 \uC788\uC5C8\uACE0, B\uB97C \uD1B5\uD574 \uD574\uACB0\uD588\uC74C\u201D \uC758 \uD750\uB984\uC73C\uB85C \uC791\uC131\uD574\uC57C \uC774\uD574\uD558\uAE30\uAC00 \uC870\uAE08 \uB354 \uC218\uC6D4\uD558\uB2E4.</li><li>\uC131\uACFC \uD639\uC740 \uC784\uD329\uD2B8\uAC00 \uC788\uC73C\uBA74 \uC88B\uC9C0\uB9CC, \uC774\uAC8C \uC5C6\uB2E4\uBA74 \u201C\uBC30\uC6B4\uC810\u201D \uD639\uC740 \u201C\uACB0\uACFC\u201D, \u201C\uC0B0\uCD9C\uBB3C\u201D \uAC19\uC740 \uAC83\uB4E4\uC774 \uC788\uC73C\uBA74 \uC88B\uB2E4. \uC131\uACFC\uB294 \uD658\uACBD\uC774 \uAF64 \uC911\uC694\uD558\uAE30 \uB54C\uBB38\uC5D0, \uC131\uACFC\uB97C \uB9CC\uB4E4 \uC218 \uC788\uB294 \uC5ED\uB7C9\uC774 \uC788\uC74C\uC744 \uBCF4\uC5EC\uC8FC\uB294 \uAC8C \uC911\uC694\uD558\uB2E4.</li></ul><h4 id="_5-\u1109\u1169\u1111\u1173\u1110\u1173\u1109\u1173\u110F\u1175\u11AF\u1103\u1169-\u110C\u116E\u11BC\u110B\u116D\u1112\u1161\u1103\u1161" tabindex="-1"><a class="header-anchor" href="#_5-\u1109\u1169\u1111\u1173\u1110\u1173\u1109\u1173\u110F\u1175\u11AF\u1103\u1169-\u110C\u116E\u11BC\u110B\u116D\u1112\u1161\u1103\u1161" aria-hidden="true">#</a> 5) \uC18C\uD504\uD2B8\uC2A4\uD0AC\uB3C4 \uC911\uC694\uD558\uB2E4.</h4><p><img src="'+f+'" alt="image.png"></p><ul><li>\uAF2D \uD300\uC758 \uB9AC\uB354\uB97C \uD558\uB294\uAC8C \uC544\uB2C8\uB77C\uB3C4, <strong>\uB9AC\uB354\uC27D\uC744 \uBC1C\uD718\uD560 \uC218 \uC788\uB294 \uC0C1\uD669</strong>\uC774 \uBD84\uBA85 \uC788\uB2E4. \uC791\uC740 \uD504\uB85C\uC81D\uD2B8\uB97C \uB9AC\uB529\uD558\uAC70\uB098 \uD639\uC740 \uD504\uB85C\uC81D\uD2B8\uB97C \uB2A5\uB3D9\uC801\uC73C\uB85C \uC774\uB04C\uC5B4\uAC00\uB294 \uAC83\uB3C4 \uB9AC\uB354\uC27D\uC774\uB2E4. \uC774\uB97C \uCE90\uCE58\uD558\uC5EC \uC5ED\uB7C9\uACFC \uC5F0\uACB0\uC9D3\uB294 \uAC83\uC774 \uC911\uC694\uD558\uB2E4.</li><li><strong>\uC77C\uC744 \uC798 \uD558\uAE30 \uC704\uD55C \uBB38\uC81C\uC815\uC758</strong>, <strong>\uBB38\uC81C\uC758 \uAD6C\uC870\uD654</strong> \uB4F1 \uBCF8\uC9C8\uC744 \uC798 \uB2E4\uB8E8\uB294 \uAC8C \uC911\uC694\uD558\uB2E4.</li></ul><h2 id="\u110C\u1165\u11BC\u1105\u1175\u1112\u1161\u110C\u1161\u1106\u1167\u11AB" tabindex="-1"><a class="header-anchor" href="#\u110C\u1165\u11BC\u1105\u1175\u1112\u1161\u110C\u1161\u1106\u1167\u11AB" aria-hidden="true">#</a> \uC815\uB9AC\uD558\uC790\uBA74</h2><ol><li>\uB098\uC758 \uD2B9\uC7A5\uC810\uC774 \uBCF4\uC5EC\uC57C \uD55C\uB2E4. \u201C\uBB34\uC5C7\uC774\uB4E0 \uC798 \uD560 \uC218 \uC788\uC74C\u201D \uBCF4\uB2E8 \u201C\uD2B9\uD788 \uC774\uB7F0 \uAC83\uB4E4\uC744 \uC798 \uD560 \uC218 \uC788\uC74C\u201D \uC744 \uBCF4\uC5EC\uC8FC\uC5B4\uC57C \uD55C\uB2E4.</li><li>\uB0B4\uAC00 \uD300\uC7A5\uC774\uB77C\uACE0 \uC0DD\uAC01\uD558\uACE0, \uB098\uC5D0\uAC8C \uC5B4\uB5A4 \uC77C\uC744 \uC2DC\uCF30\uC744 \uB54C \uC81C\uC77C \uC784\uD329\uD2B8\uAC00 \uC788\uC744\uC9C0 \uC0C1\uC0C1\uD574\uBCF4\uC790.</li><li>\uAE4A\uAC8C \uACE0\uBBFC\uD55C \uAC83\uB4E4\uC744 \uC798 \uD480\uC5B4\uB0BC \uC218 \uC788\uC5B4\uC57C \uD55C\uB2E4.</li><li>\uC774\uB825\uC774 \uC5ED\uB7C9 \uB2E8\uC704\uB85C \uCE74\uD14C\uACE0\uB77C\uC774\uC9D5 \uB418\uC5B4\uC57C \uD55C\uB2E4.</li><li>\uB098\uC758 \uAC15\uC810\uC5D0 \uB300\uD574 \uBA85\uD655\uD558\uAC8C \uC124\uBA85\uD560 \uC218 \uC788\uC5B4\uC57C \uD55C\uB2E4.</li></ol><h2 id="one-more-thing" tabindex="-1"><a class="header-anchor" href="#one-more-thing" aria-hidden="true">#</a> One more thing</h2><p>\uC774\uB825\uC11C\uB97C \uC791\uC131\uD558\uB294\uAC74 \uC27D\uC9C0 \uC54A\uB2E4. \uB098\uC5D0 \uB300\uD574\uC11C \uB0B4\uAC00 \uC798 \uC54C\uC544\uC57C \uD558\uACE0, \uB098\uC758 \uAC15\uC810\uACFC \uC5ED\uB7C9\uC744 \uCE90\uCE58\uD574\uC11C \uD45C\uD604\uD574\uC57C \uD55C\uB2E4. \uB098\uB294 \uC774\uB825\uC11C\uC758 \uD575\uC2EC\uC774 <u><strong>\u201C\uB098\uC5D0 \uB300\uD574 \uC798 \uC774\uD574\uD558\uB294 \uAC83\u201D</strong></u> \uC774\uB77C\uACE0 \uC0DD\uAC01\uD55C\uB2E4. <strong>\uB0B4\uAC00 \uB098\uC5D0 \uB300\uD574 \uC798 \uC774\uD574\uD558\uAE30 \uC704\uD574 \uC2DC\uB3C4\uD558\uB294 \uAC83\uC740 \u201C\uAE00\uC4F0\uAE30\u201D\uC774\uB2E4.</strong> \uC77C\uAE30\uAC00 \uB420 \uC218\uB3C4 \uC788\uACE0, \uD68C\uACE0\uAC00 \uB420 \uC218\uB3C4 \uC788\uB2E4. \uAF2D \uB0A8\uC5D0\uAC8C \uBCF4\uC5EC\uC8FC\uC9C0 \uC54A\uC544\uB3C4 \uAD1C\uCC2E\uB2E4.</p><p>\uD68C\uC0AC\uC0DD\uD65C\uC5D0 \uB300\uD574 \uC368\uBCF4\uB294 \uAC83\uB3C4 \uC88B\uACE0, \uC77C\uC0C1\uC5D0\uC11C \uACAA\uB294 \uC77C\uB4E4\uC5D0 \uB300\uD574 \uC368\uBCF4\uB294 \uAC83\uB3C4 \uC88B\uB2E4. \uBB34\uC5C7\uC774 \uB418\uC5C8\uB4E0 \uB098\uC5D0 \uB300\uD574\uC11C \uC4F0\uB2E4 \uBCF4\uBA74 \uB098\uB97C \uB354 \uC798 \uC774\uD574\uD560 \uC218 \uC788\uAC8C \uB418\uACE0, \uB098\uB97C \uD45C\uD604\uD558\uB294 \uAC83\uC774 \uC790\uC5F0\uC2A4\uB7EC\uC6CC\uC9C0\uB294 \uC2DC\uC810\uC774 \uBD84\uBA85 \uC788\uC744 \uAC83\uC774\uB2E4.</p><p><strong>\uC774\uB825\uC11C \uC791\uC131\uACFC \uBA74\uC811\uC758 \uBCF8\uC9C8\uC740 \u201C\uB098\uB97C \uD45C\uD604\uD558\uB294 \uAC83\u201D \uC774\uB2E4.</strong> \uB098\uC5D0 \uB300\uD574 \uC798 \uC774\uD574\uD560 \uC218 \uC788\uB2E4\uBA74 \uB098\uB97C \uD45C\uD604\uD558\uB294 \uAC83\uB3C4 \uC790\uC5F0\uC2A4\uB7EC\uC6CC\uC9C0\uC9C0 \uC54A\uC744\uAE4C? \uADF8\uB9AC\uACE0 \uC774\uAC8C \uC790\uC5F0\uC2A4\uB7EC\uC6B8 \uB54C <strong>\uB354 \uC5B4\uB835\uACE0 \uB09C\uD574\uD55C \uBB38\uC81C\uB97C \uD480\uC774\uD560 \uC218 \uC788\uC73C\uB9AC\uB77C \uC0DD\uAC01</strong>\uD55C\uB2E4.</p><h2 id="reference" tabindex="-1"><a class="header-anchor" href="#reference" aria-hidden="true">#</a> Reference</h2>',51),k={href:"https://blog.shiren.dev/ko/post/2025-02-28",target:"_blank",rel:"noopener noreferrer"},w=i("\uC774\uB825\uC11C \uC8FC\uB3C4 \uACBD\uB825 \uAC1C\uBC1C"),x={href:"https://jojoldu.github.io/",target:"_blank",rel:"noopener noreferrer"},I=i("\uC778\uD504\uB7A9 CTO \uC774\uB3D9\uC6B1\uB2D8\uC758 \uC774\uB825\uC11C"),N={href:"https://the-next-web-research-lab.github.io/fe-dev/self-management/project-history.html",target:"_blank",rel:"noopener noreferrer"},T=i("\uB0B4 \uCEE4\uB9AC\uC5B4\uB97C \uC704\uD55C \uC5C5\uBB34 \uC774\uB825 \uAD00\uB9AC");function L(j,A){const a=s("ExternalLinkIcon");return t(),o("div",null,[v,e("ul",null,[e("li",null,[e("a",k,[w,r(a)])]),e("li",null,[e("a",x,[I,r(a)])]),e("li",null,[e("a",N,[T,r(a)])])])])}var E=n(b,[["render",L],["__file","index.html.vue"]]);export{E as default};
